<?php
namespace App\Modules\Tenancy\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Tenancy\Services\OfficineAccess as Access;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
class OfficeLogoController extends Controller {
 public function show(Request $r){abort_unless($r->attributes->get('officine.access_type')==='member'||in_array('officine.read',$r->attributes->get('officine.permissions',[]),true),403);$path=DB::table('officines')->where('id',app('tenant.officine_id'))->value('logo_path');abort_unless($path&&Storage::disk('local')->exists($path),404);return response(Storage::disk('local')->get($path))->header('Content-Type','image/png')->header('X-Content-Type-Options','nosniff')->header('Cache-Control','no-store');}
 public function save(Request $r){$id=Access::admin($r);$d=$r->validate(['profile_version'=>['required','integer','min:1'],'file'=>['required','image','mimes:png,jpg,jpeg','max:2048','dimensions:max_width=2000,max_height=2000']]);abort_unless(function_exists('imagecreatefromstring'),503,'Traitement des images indisponible.');$image=@imagecreatefromstring($r->file('file')->get());abort_unless($image,422,'Image invalide.');imagesavealpha($image,true);ob_start();imagepng($image);$bytes=ob_get_clean();imagedestroy($image);$path='office-logos/'.Str::uuid().'.png';abort_unless(Storage::disk('local')->put($path,$bytes),503,'Stockage indisponible.');try{$old=DB::transaction(function()use($r,$id,$d,$path,$bytes){$o=Access::lockAdmin($r,$id);abort_unless($o->profile_version===(int)$d['profile_version'],409,'Version périmée. Rechargez la fiche.');DB::table('officines')->where('id',$id)->update(['logo_path'=>$path,'logo_sha256'=>hash('sha256',$bytes),'profile_version'=>$o->profile_version+1,'updated_at'=>now()]);Access::audit($r,$id,'officine.logo.updated',['version'=>$o->profile_version+1]);return $o->logo_path;});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}if($old)Storage::disk('local')->delete($old);return response()->json(['message'=>'Logo privé enregistré.']);}
 public function destroy(Request $r){$id=Access::admin($r);$d=$r->validate(['profile_version'=>['required','integer','min:1']]);$path=DB::transaction(function()use($r,$id,$d){$o=Access::lockAdmin($r,$id);abort_unless($o->profile_version===(int)$d['profile_version'],409,'Version périmée.');DB::table('officines')->where('id',$id)->update(['logo_path'=>null,'logo_sha256'=>null,'profile_version'=>$o->profile_version+1,'updated_at'=>now()]);Access::audit($r,$id,'officine.logo.removed',['version'=>$o->profile_version+1]);return $o->logo_path;});if($path)Storage::disk('local')->delete($path);return response()->json(['message'=>'Logo retiré.']);}
}
